import pathlib,json,csv,hashlib,sys,io,contextlib
import numpy as np,torch
torch.set_num_threads(1)
torch.set_num_interop_threads(1)
sys.path.insert(0,str(pathlib.Path('rsl_rl').resolve()))
from rsl_rl.modules.actor_critic_roa import ActorCriticROA
root=pathlib.Path.cwd()
refroot=root/'learnings/policy_tuning/RobotLab-Isaac-Velocity-Flat-LW-wheel-Roa-v0/2026-09-21_20-20-10/evidence/analysis/roa-delay30-same-observation-20260922'
historical=json.loads((refroot/'metrics.json').read_text())
def ref(p):
 p=pathlib.Path(p).resolve()
 return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
for r in [historical['data'],historical['artifacts']['csv']]:
 assert ref(r['path'])['sha256']==r['sha256'],r['path']
rows=list(csv.DictReader(open(historical['data']['path'])))
names=historical['method']['joint_order']
default=np.array(historical['method']['q_default'],dtype=np.float32)
scale=np.array(historical['method']['action_scale'],dtype=np.float32)
def vector(r,keys):return np.array([float(r[k]) for k in keys],dtype=np.float32)
def target(r):
 return vector(r,[n+'_target.'+('position' if j<8 else 'velocity') for j,n in enumerate(names)])
frames=[];times=[];qs=[];dqs=[]
for i in range(3200,3229):
 r=rows[i-1]
 q=vector(r,[n+'_now.position' for n in names])
 dq=vector(r,[n+'_now.velocity' for n in names])
 gyro=vector(r,['imu_ang_vel.'+c for c in ['position','velocity','effort']])
 quat=vector(r,['imu_quat_'+c+'.position' for c in ['w','x','y','z']])
 w=quat[0];v=quat[1:];g=np.array([0,0,-1],dtype=np.float32)
 gravity=g*(2*w*w-1)-2*w*np.cross(v,g)+2*v*np.dot(v,g)
 qrel=q-default;qrel[8:]=0
 prev=np.zeros(10,dtype=np.float32) if i==3200 else (target(r)-default)/scale
 cmd=vector(r,['cmd_vel.'+c for c in ['position','velocity','effort']])
 frames.append(np.concatenate([gyro*.25,gravity,cmd,qrel,dq*.05,prev]))
 times.append(float(rows[i]['time_s'])-float(rows[3200]['time_s']))
 qs.append(q);dqs.append(dq)
frames=np.array(frames);times=np.array(times);qs=np.array(qs);dqs=np.array(dqs)
hist=np.stack([np.stack([frames[max(0,j)] for j in range(i-9,i+1)]) for i in range(29)])
H=torch.from_numpy(hist.copy())
def load(run,ck):
 p=root/'logs/rsl_rl/LW_wheel_flat_roa'/run/ck
 d=torch.load(p,map_location='cpu',weights_only=False);state=d['model_state_dict']
 obs={'policy':torch.zeros(1,10,39),'critic':torch.zeros(1,state['critic.0.weight'].shape[1]),'privileged':torch.zeros(1,state['priv_encoder.0.weight'].shape[1])}
 with contextlib.redirect_stdout(io.StringIO()):
  model=ActorCriticROA(obs,{'policy':['policy'],'critic':['critic'],'privileged':['privileged']},10,actor_hidden_dims=[512,256,128],critic_hidden_dims=[512,256,128],priv_encoder_dims=[64,20],activation='elu',vel_offset=39,use_velocity_estimation=True)
  model.load_state_dict(state,strict=True)
 model.eval()
 return model,ref(p)
def infer(model,h):
 with torch.inference_mode():return model.act_inference({'policy':h},hist_encoding=True)
m,p=load('2026-09-16_15-12-04','model_49999.pt')
y=infer(m,H).numpy()*scale+default
oldrows=[r for r in csv.DictReader(open(refroot/'replay_and_sensitivity.csv')) if r['model']=='2026-09-16_15-12-04']
old=np.array([[float(r['baseline.right_hip_target_rad']),float(r['baseline.left_hip_target_rad'])] for r in oldrows])
print('CALIBRATION',json.dumps({'first_target':y[0,:2].tolist(),'old_first_target':old[0].tolist(),'old_hip_replay_max_error':float(abs(y[:,:2]-old).max()),'recorded_after10_legs_max_error':float(abs(y[10:,:8]-np.stack([target(r) for r in rows[3210:3229]])[:,:8]).max()),'recorded_after10_wheels_max_error':float(abs(y[10:,8:]-np.stack([target(r) for r in rows[3210:3229]])[:,8:]).max())}))
assert abs(y[:,:2]-old).max()<1e-5

from datetime import datetime,timezone
import os
cases=[('latest_final','2026-09-23_17-23-24','model_49999.pt'),('previous_11000','2026-09-23_11-31-50','model_11000.pt'),('sep16_final','2026-09-16_15-12-04','model_49999.pt'),('sep19_final','2026-09-19_11-41-48','model_49999.pt'),('sep21_final','2026-09-21_20-20-10','model_49999.pt')]
windows={'full_0_560ms':(0,29),'first_300ms':(0,16),'history_filled_200_300ms':(10,16),'history_filled_200_560ms':(10,29)}
result={};arrays={};csvrows=[];checks={}
for label,run,ck in cases:
 model,checkpoint=load(run,ck)
 if label=='latest_final':assert checkpoint['sha256']=='4ed632b8da31fec8a3a76d4917cd8fd5e94917e9f79ed35a2a2d4ce2d1fb88b1'
 if ck=='model_49999.pt' and run in historical['models']:assert checkpoint==historical['models'][run]['checkpoint']
 with torch.inference_mode():
  baseline=infer(model,H);lat,vel=model.history_encoder(H.flatten(1))
  def direct(cur,latent=lat,velocity=vel):
   return model.actor(torch.cat([cur,velocity,latent],dim=-1))
  assert torch.max(torch.abs(direct(H[:,-1])-baseline)).item()<1e-6
  frozen=H[:,-1].clone();frozen[:,9:11]=H[0,-1,9:11];frozen[:,19:21]=H[0,-1,19:21]
  allfrozen=H.clone();allfrozen[:,:,9:11]=H[0,-1,9:11];allfrozen[:,:,19:21]=H[0,-1,19:21]
  outputs={'baseline':baseline,'freeze_current_hip':direct(frozen),'freeze_all_history_hip':infer(model,allfrozen),'zero_velocity_code':direct(H[:,-1],velocity=torch.zeros_like(vel))}
  physical={k:v.numpy().astype(np.float64)*scale+default for k,v in outputs.items()}
  jac={}
  for mode in ['full_model_current','actor_direct']:
   for kind,col,eps,inscale in [('q',9,.001,1.),('dq',19,.01,.05)]:
    pairs=[]
    for factor in [1,2]:
     J=np.zeros((29,2,2),dtype=np.float64)
     for j in range(2):
      plus=H.clone();minus=H.clone()
      plus[:,-1,col+j]+=eps*factor*inscale;minus[:,-1,col+j]-=eps*factor*inscale
      ap=infer(model,plus) if mode=='full_model_current' else direct(plus[:,-1])
      am=infer(model,minus) if mode=='full_model_current' else direct(minus[:,-1])
      J[:,:,j]=((ap[:,:2]-am[:,:2])*.25/(2*eps*factor)).numpy()
     pairs.append(J)
    jac[mode+'_'+kind]=pairs
  full_joint_jac={}
  for kind,col,n_input,eps,inscale in [('q',9,8,.001,1.),('dq',19,10,.01,.05)]:
   both=[]
   for factor in [1,2]:
    J=np.zeros((29,10,n_input),dtype=np.float64)
    for j in range(n_input):
     hp=H.clone();hm=H.clone()
     hp[:,-1,col+j]+=eps*factor*inscale;hm[:,-1,col+j]-=eps*factor*inscale
     ap=infer(model,hp);am=infer(model,hm)
     J[:,:,j]=(ap-am).numpy()*scale[None,:]/(2*eps*factor)
    both.append(J)
   full_joint_jac[kind]=both
  consistency={}
  for k,(j1,j2) in jac.items():
   rel=np.linalg.norm(j1-j2,axis=(1,2))/np.maximum(np.linalg.norm(j1,axis=(1,2)),1e-12)
   consistency[k]={'median_relative_change':float(np.median(rel)),'max_relative_change':float(rel.max())}
  win={}
  for w,(lo,hi) in windows.items():
   win[w]={'outputs':{},'sensitivity':{},'per_joint':{}}
   for k,v in physical.items():
    hip=v[lo:hi,:2]
    win[w]['outputs'][k]={'hip_target_absmax_rad':float(abs(hip).max()),'hip_target_step_rms_rad':float(np.sqrt(np.mean(np.diff(hip,axis=0)**2))),'hip_difference_from_baseline_rms_rad':float(np.sqrt(np.mean((hip-physical['baseline'][lo:hi,:2])**2)))}
   for k,(j1,j2) in jac.items():
    singular=np.linalg.svd(j1[lo:hi],compute_uv=False)[:,0]
    win[w]['sensitivity'][k]={'spectral_norm_median':float(np.median(singular)),'spectral_norm_max':float(singular.max())}
   for j,name in enumerate(names):
    v=physical['baseline'][lo:hi,j];a=baseline.numpy()[lo:hi,j].astype(np.float64)
    win[w]['per_joint'][name]={'target_unit':'rad' if j<8 else 'rad/s','target_absmax':float(abs(v).max()),'target_step_rms':float(np.sqrt(np.mean(np.diff(v)**2))),'target_second_difference_rms':float(np.sqrt(np.mean(np.diff(v,n=2)**2))),'raw_action_step_mean_square':float(np.mean(np.diff(a)**2)),'raw_action_second_difference_mean_square':float(np.mean(np.diff(a,n=2)**2))}
  entry={}
  for kind,col,delta,inscale in [('q',9,.01,1.),('dq',19,.1,.05)]:
   changes={}
   for sign in [1,-1]:
    h=H[:1].clone();h[:,-1,col]+=delta*sign*inscale;h[:,-1,col+1]-=delta*sign*inscale
    changes[str(sign)]=((infer(model,h)[0,:2]-baseline[0,:2])*.25).tolist()
   entry[kind]={'physical_input_R_L':[delta,-delta],'target_changes_rad':changes}
  result[label]={'run':run,'checkpoint':checkpoint,'windows':win,'first_target_hip_rad':physical['baseline'][0,:2].tolist(),'first_nominal_pd_Nm':(90*(physical['baseline'][0,:2]-qs[0,:2])-3*dqs[0,:2]).tolist(),'entry_sensitivity':entry,'finite_difference_consistency':consistency,'raw_action_absmax':float(baseline.abs().max()),'parameter_nonfinite_count':sum(int((~torch.isfinite(v)).sum()) for v in model.state_dict().values()),'config_refs':[ref(root/'logs/rsl_rl/LW_wheel_flat_roa'/run/'params'/n) for n in ['env.yaml','agent.yaml']]}
  joint_sensitivity={}
  for w,(lo,hi) in windows.items():
   joint_sensitivity[w]={}
   for j,name in enumerate(names):
    item={}
    for kind,(j1,j2) in full_joint_jac.items():
     vals=j1[lo:hi,j,:]
     item[kind+'_row_l2_median']=float(np.median(np.linalg.norm(vals,axis=1)))
     if j<vals.shape[-1]:
      item[kind+'_self_abs_median']=float(np.median(np.abs(vals[:,j])))
    joint_sensitivity[w][name]=item
  result[label]['all_joint_sensitivity']=joint_sensitivity
  result[label]['all_joint_sensitivity_units']='q: 8 leg positions in rad; dq: all 10 velocities in rad/s. Outputs: 8 position targets in rad and 2 wheel velocity targets in rad/s. Compare only matching units.'
  for kind,(j1,j2) in full_joint_jac.items():
   rel=np.linalg.norm(j1-j2,axis=(1,2))/np.maximum(np.linalg.norm(j1,axis=(1,2)),1e-12)
   result[label]['finite_difference_consistency']['all_joint_'+kind]={'max_relative_change':float(rel.max()),'median_relative_change':float(np.median(rel))}
  if ck=='model_49999.pt' and run in historical['models']:
   archived=[r for r in csv.DictReader(open(refroot/'replay_and_sensitivity.csv')) if r['model']==run]
   archived_targets=np.array([[float(r['baseline.right_hip_target_rad']),float(r['baseline.left_hip_target_rad'])] for r in archived])
   err=float(abs(physical['baseline'][:,:2]-archived_targets).max());assert err<1e-5
   checks[label]={'archived_target_max_abs_error_rad':err}
  for i in range(29):
   row={'model':label,'row_index':3200+i,'relative_bag_time_s':float(times[i])}
   for j,name in enumerate(names):
    row[name+'.raw_action']=float(baseline[i,j]);row[name+'.target']=float(physical['baseline'][i,j])
   for mode,v in physical.items():
    for j in range(2):row[mode+'.'+names[j]+'_target_rad']=float(v[i,j])
   for key,(j1,j2) in jac.items():
    for ei,J in enumerate([j1,j2]):
     for u in range(2):
      for v in range(2):row[key+f'.eps{ei+1}.dtarget{u}_dinput{v}']=float(J[i,u,v])
   for kind,(j1,j2) in full_joint_jac.items():
    for ei,J in enumerate([j1,j2]):
     for u in range(10):
      for v in range(J.shape[-1]):row['all_joint_'+kind+f'.eps{ei+1}.dtarget{u}_dinput{v}']=float(J[i,u,v])
   csvrows.append(row)
  arrays[label]={'targets':physical['baseline'],'sensitivity_q':np.linalg.svd(jac['full_model_current_q'][0],compute_uv=False)[:,0],'sensitivity_dq':np.linalg.svd(jac['full_model_current_dq'][0],compute_uv=False)[:,0]}
 print('MODEL',label,json.dumps({'first':result[label]['first_target_hip_rad'],'filled':win['history_filled_200_560ms']['outputs']['baseline'],'early':win['history_filled_200_300ms']['outputs']['baseline'],'q_gain':win['history_filled_200_560ms']['sensitivity']['full_model_current_q'],'dq_gain':win['history_filled_200_560ms']['sensitivity']['full_model_current_dq'],'consistency':consistency}),flush=True)
# Existing completed policies are historical references on the same input, not new hardware observations.
references={k:v for k,v in historical['models'].items() if k in ['2026-09-19_11-41-48','DWAQ historical']}
changes={}
for label in ['previous_11000','sep16_final','sep19_final','sep21_final']:
 changes[label]={}
 for window in windows:
  cur=result['latest_final']['windows'][window];old=result[label]['windows'][window]
  changes[label][window]={}
  for key in ['hip_target_absmax_rad','hip_target_step_rms_rad']:
   changes[label][window][key]=100*(cur['outputs']['baseline'][key]/old['outputs']['baseline'][key]-1)
  for key in ['full_model_current_q','full_model_current_dq']:
   changes[label][window][key]=100*(cur['sensitivity'][key]['spectral_norm_median']/old['sensitivity'][key]['spectral_norm_median']-1)
print('CHANGES',json.dumps(changes),flush=True)
# Publish permanent analysis evidence only after input mapping and reference replay checks.
out=root/'learnings/policy_tuning/RobotLab-Isaac-Velocity-Flat-LW-wheel-Roa-v0/2026-09-23_17-23-24/evidence/analysis/static-realdata-final-20260924-001'
assert not out.exists(),str(out)
out.mkdir(parents=True,exist_ok=False)
with open(out/'replay_and_sensitivity.csv','x',newline='') as f:
 writer=csv.DictWriter(f,fieldnames=list(csvrows[0]),lineterminator='\n');writer.writeheader();writer.writerows(csvrows)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig,axes=plt.subplots(2,2,figsize=(12,8))
labels={'latest_final':'Latest Sep23 17:23 / final','previous_11000':'Prior Sep23 11:31 / 11k','sep19_final':'Sep19 / final (hip penalty)','sep16_final':'Sep16 / final','sep21_final':'Sep21 / final (30ms)'}
for label,a in arrays.items():
 for j in range(2):axes[0,j].plot(times*1000,a['targets'][:,j],label=labels[label],linewidth=1.5)
 axes[1,0].plot(times*1000,a['sensitivity_q'],label=labels[label],linewidth=1.5)
 axes[1,1].plot(times*1000,a['sensitivity_dq'],label=labels[label],linewidth=1.5)
titles=['Right hip target','Left hip target','Hip position sensitivity: largest singular value','Hip velocity sensitivity: largest singular value']
units=['rad','rad','rad/rad','rad/(rad/s)']
for ax,title,unit in zip(axes.flat,titles,units):
 ax.set_title(title);ax.set_xlabel('Recorded time from policy entry (ms)');ax.set_ylabel(unit);ax.axvspan(0,times[10]*1000,color='gray',alpha=.10);ax.grid(alpha=.25)
axes[0,0].legend(fontsize=8)
fig.suptitle('Same recorded inputs / deterministic CPU replay / no action feedback\nShaded: approximate startup history. No physical rollout.',fontsize=11)
fig.tight_layout();fig.savefig(out/'comparison.png',dpi=160);plt.close(fig)
method=dict(historical['method']);method.update({'models':'Latest Sep23 17:23 final vs previous Sep23 11:31 model_11000 and Sep16/Sep19/Sep21 finals; DWAQ historical reference only','initial_previous_action':'zero for first reconstructed frame; later inferred from original recorded targets','window_indices_exclusive':windows,'per_joint_differences':'Within-window differences; no cross-window boundary samples. Position outputs for 8 leg joints, velocity outputs for 2 wheels. No dt normalization for target step metrics.'})
limits=list(historical['limitations'])+['Latest checkpoint completed 50k iterations. Previous Sep23 11:31 checkpoint has only 11k iterations and different rewards; its comparison confounds training progress and multiple parameter changes.','Static target differences reflect responses to already oscillating old-policy states; they do not predict the new policy closed-loop trajectory.','29 frames do not support robust oscillation-frequency or stability-margin estimates.']
payload={'schema_version':1,'created_at':datetime.now(timezone.utc).isoformat(),'analysis_kind':'User-authorized static replay of prior hardware oscillation data','data':historical['data'],'historical_metrics':ref(refroot/'metrics.json'),'historical_csv':ref(refroot/'replay_and_sensitivity.csv'),'models':result,'historical_references':references,'changes_pct_current_vs':changes,'method':method,'checks':checks,'source':ref(root/'rsl_rl/rsl_rl/modules/actor_critic_roa.py'),'training_source_snapshot':ref(root/'logs/rsl_rl/LW_wheel_flat_roa/2026-09-23_17-23-24/git/robot_lab.diff'),'analysis_source':{'sha256':hashlib.sha256(REPLAY_SOURCE.encode()).hexdigest(),'python':REPLAY_SOURCE},'artifacts':{'csv':ref(out/'replay_and_sensitivity.csv'),'plot':ref(out/'comparison.png')},'limitations':limits,'direct_parameter_change_supported':False}
with open(out/'metrics.json','x') as f:json.dump(payload,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
# Verify source references, emitted rows and read-back numbers.
refs=[payload['data'],payload['historical_metrics'],payload['historical_csv'],payload['source'],payload['training_source_snapshot'],*payload['artifacts'].values()]
for item in result.values():refs.extend([item['checkpoint'],*item['config_refs']])
for r in refs:assert ref(r['path'])==r
saved=json.loads((out/'metrics.json').read_text());savedrows=list(csv.DictReader(open(out/'replay_and_sensitivity.csv')));assert len(savedrows)==145
assert saved['models']==result
verification={'verified_at':datetime.now(timezone.utc).isoformat(),'metrics':ref(out/'metrics.json'),'reference_hashes_verified':len(refs),'csv_rows':len(savedrows),'frames_per_model':29,'archived_replay_checks':checks,'scope':'CPU only; no simulator, hardware, optimizer, training parameter or code edits','plot_visually_reviewed':False}
with open(out/'verification.json','x') as f:json.dump(verification,f,ensure_ascii=False,indent=2);f.write('\n')
print('OUTPUT',str(out),flush=True)
